classdef EnumTargetRotationalDynamicsModel < uint8
    %% SIGNATURE
    % enumModel = EnumTargetRotationalDynamicsModel.<Value>
    % -------------------------------------------------------------------------------------------------------------
    %% DESCRIPTION
    % Select whether target rotation is supplied externally, generated with constant inertial angular velocity, or
    % generated by torque-free rigid-body kino-dynamics integration.
    % -------------------------------------------------------------------------------------------------------------
    %% INPUT
    % None.
    % -------------------------------------------------------------------------------------------------------------
    %% OUTPUT
    % enumModel    (1,1) EnumTargetRotationalDynamicsModel
    % -------------------------------------------------------------------------------------------------------------
    %% CHANGELOG
    % 22-08-2026  Pietro Califano, Codex     First implementation.
    % 11-11-2026  Pietro Califano, Claude Opus 5.5   Readability pass.
    % -------------------------------------------------------------------------------------------------------------
    %% DEPENDENCIES
    % None.
    % -------------------------------------------------------------------------------------------------------------

    enumeration
        SOURCE_PROVIDED               (1)
        KINEMATIC_CONST_INERTIAL_RATE (2)
        RIGID_BODY_TORQUE_FREE        (3)
    end

    methods (Static)
        function enumModel = FromConfigValue(varModel)
            %% SIGNATURE
            % enumModel = EnumTargetRotationalDynamicsModel.FromConfigValue(varModel)
            % -------------------------------------------------------------------------------------------------
            %% DESCRIPTION
            % Normalize a scalar configuration token or preserve an existing typed dynamics model.
            % -------------------------------------------------------------------------------------------------
            %% INPUT
            % varModel    EnumTargetRotationalDynamicsModel, char, or string scalar
            % -------------------------------------------------------------------------------------------------
            %% OUTPUT
            % enumModel   (1,1) EnumTargetRotationalDynamicsModel
            % -------------------------------------------------------------------------------------------------
            %% CHANGELOG
            % 22-08-2026  Pietro Califano, Codex     First implementation.
            % -------------------------------------------------------------------------------------------------
            %% DEPENDENCIES
            % None.
            % -------------------------------------------------------------------------------------------------

            arguments (Input)
                varModel {mustBeA(varModel, ["EnumTargetRotationalDynamicsModel", "char", "string"])}
            end
            arguments (Output)
                enumModel (1,1) EnumTargetRotationalDynamicsModel
            end

            % Accept a scalar enum value as is
            if isa(varModel, 'EnumTargetRotationalDynamicsModel')
                if ~isscalar(varModel)
                    error('EnumTargetRotationalDynamicsModel:NonScalarModel', ...
                        'Target rotational dynamics model must be scalar.');
                end
                enumModel = varModel;
                return
            end

            % Map a text token to the enum, ignoring case and surrounding blanks and reading '-' as '_'
            mustBeTextScalar(varModel);
            charModel = upper(strrep(char(strip(string(varModel))), '-', '_'));
            switch charModel
                case 'SOURCE_PROVIDED'
                    enumModel = EnumTargetRotationalDynamicsModel.SOURCE_PROVIDED;
                case 'KINEMATIC_CONSTANT_INERTIAL_RATE'
                    enumModel = EnumTargetRotationalDynamicsModel.KINEMATIC_CONST_INERTIAL_RATE;
                case 'RIGID_BODY_TORQUE_FREE'
                    enumModel = EnumTargetRotationalDynamicsModel.RIGID_BODY_TORQUE_FREE;
                otherwise
                    error('EnumTargetRotationalDynamicsModel:UnsupportedModel', ...
                        'Unsupported target rotational dynamics model "%s".', charModel);
            end
        end

        function charModel = ToConfigValue(enumModel)
            %% SIGNATURE
            % charModel = EnumTargetRotationalDynamicsModel.ToConfigValue(enumModel)
            % -------------------------------------------------------------------------------------------------
            %% DESCRIPTION
            % Convert a typed dynamics model to its canonical lowercase configuration token.
            % -------------------------------------------------------------------------------------------------
            %% INPUT
            % enumModel    (1,1) EnumTargetRotationalDynamicsModel
            % -------------------------------------------------------------------------------------------------
            %% OUTPUT
            % charModel    (1,:) char canonical configuration token
            % -------------------------------------------------------------------------------------------------
            %% CHANGELOG
            % 22-08-2026  Pietro Califano, Codex     First implementation.
            % -------------------------------------------------------------------------------------------------
            %% DEPENDENCIES
            % None.
            % -------------------------------------------------------------------------------------------------

            arguments (Input)
                enumModel (1,1) EnumTargetRotationalDynamicsModel
            end
            arguments (Output)
                charModel (1,:) char
            end

            switch enumModel
                case EnumTargetRotationalDynamicsModel.SOURCE_PROVIDED
                    charModel = 'source_provided';
                case EnumTargetRotationalDynamicsModel.KINEMATIC_CONST_INERTIAL_RATE
                    charModel = 'kinematic_constant_inertial_rate';
                case EnumTargetRotationalDynamicsModel.RIGID_BODY_TORQUE_FREE
                    charModel = 'rigid_body_torque_free';
                otherwise
                    error('EnumTargetRotationalDynamicsModel:UnsupportedEnumValue', ...
                        'Unsupported typed target rotational dynamics model.');
            end
        end
    end
end
